def count_perfect_numbers_in_range(a, b):
    def proper_sum(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total
    count = 0
    for x in range(max(a, 1), b + 1):
        if x > 1 and proper_sum(x) == x:
            count += 1
    return count

def set_nested(d, path, value, sep):
    import copy
    result = copy.deepcopy(d)
    parts = path.split(sep)
    cur = result
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    cur[parts[-1]] = value
    return result

def reorder_by_priority_list(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    listed = [x for x in items if x in pos]
    unlisted = [x for x in items if x not in pos]
    listed.sort(key=lambda x: pos[x])
    return listed + unlisted

def common_dedent(lines):
    non_empty = [l for l in lines if l.strip() != ""]
    if not non_empty:
        return list(lines)
    min_indent = min(len(l) - len(l.lstrip(" ")) for l in non_empty)
    return [l[min_indent:] if l.strip() != "" else l for l in lines]

def years_months_days_between(d1, d2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
    y1, m1, dd1 = d1
    y2, m2, dd2 = d2
    days = dd2 - dd1
    months = m2 - m1
    years = y2 - y1
    if days < 0:
        pm = m2 - 1
        py = y2
        if pm == 0:
            pm = 12
            py -= 1
