def is_valid_css_rgb_string(s):
    import re
    m = re.fullmatch(r'rgb\((\d{1,3}), (\d{1,3}), (\d{1,3})\)', s)
    if not m:
        return False
    for part in m.groups():
        if len(part) > 1 and part[0] == '0':
            return False
        if int(part) > 255:
            return False
    return True

def sort_by_num_divisors(nums):
    def ndiv(x):
        return sum(1 for i in range(1, x + 1) if x % i == 0)
    return sorted(nums, key=lambda x: (ndiv(x), x))

def normalize_to_percentage(counts):
    total = sum(counts.values())
    if total == 0:
        return {k: 0 for k in counts}
    return {k: round(100 * v / total, 2) for k, v in counts.items()}

