def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    rev = int(str(n)[::-1])
    return is_prime(n) and is_prime(rev) and rev != n

def business_days_between(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    o1 = ordinal(date1)
    o2 = ordinal(date2)
    count = 0
    for o in range(o1, o2):
        if (o + 5) % 7 not in (5, 6):
            count += 1
    return count

def dhms_to_seconds(s):
    dpart, rest = s.split("d ")
    h, m, sec = rest.split(":")
    return int(dpart) * 86400 + int(h) * 3600 + int(m) * 60 + int(sec)

def is_valid_uk_postcode_simplified(s):
    if s.count(' ') != 1:
        return False
    outward, inward = s.split(' ')
    if not (2 <= len(outward) <= 4):
        return False
    if not outward[0].isalpha() or not outward.isalnum():
        return False
    if len(inward) != 3:
        return False
    return inward[0].isdigit() and inward[1].isalpha() and inward[2].isalpha()

