def is_valid_sudoku_diagonal(board):
    if len(board) != 9 or any(len(r) != 9 for r in board):
        return False
    seen = set()
    for i in range(9):
        v = board[i][i]
        if not isinstance(v, int) or v < 0 or v > 9:
            return False
        if v != 0:
            if v in seen:
                return False
            seen.add(v)
    return True

def is_balanced_curly(s):
    depth = 0
    for c in s:
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def clock_angle_diff(hour, minute):
    hour_angle = (hour % 12) * 30 + minute * 0.5
    minute_angle = minute * 6
    diff = abs(hour_angle - minute_angle)
    return min(diff, 360 - diff)

def second_largest_distinct(lst):
